-- TieTheKnot production schema. Apply with Supabase CLI before deploying the API.
create extension if not exists pgcrypto;
create type public.account_status as enum ('pending', 'active', 'suspended');
create type public.member_role as enum ('owner', 'planner', 'viewer');
create type public.rsvp_status as enum ('pending', 'accepted', 'declined');
create type public.invitation_status as enum ('draft', 'sent', 'opened', 'responded', 'revoked');
create type public.task_status as enum ('not_started', 'in_progress', 'completed', 'cancelled');

create table public.profiles (id uuid primary key default gen_random_uuid(), username text not null unique check (username = lower(username)), password_hash text not null, full_name text not null check (char_length(full_name) between 1 and 120), contact_number text not null check (char_length(contact_number) between 1 and 40), secret_question text, secret_answer_hash text, is_admin boolean not null default false, status public.account_status not null default 'pending', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.workspaces (id uuid primary key default gen_random_uuid(), name text not null check (char_length(name) between 1 and 160), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.workspace_members (workspace_id uuid not null references public.workspaces(id) on delete cascade, profile_id uuid not null references public.profiles(id) on delete cascade, role public.member_role not null default 'planner', created_at timestamptz not null default now(), primary key (workspace_id, profile_id));
create table public.events (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, title text not null check (char_length(title) between 1 and 160), target_date date, guest_expected_count integer not null default 0 check (guest_expected_count >= 0), guest_initialized boolean not null default false, budget numeric(14,2) not null default 0 check (budget >= 0), budget_initialized boolean not null default false, invitation_settings jsonb not null default '{"seatingReleased":false}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index events_workspace_id_idx on public.events(workspace_id);

create table public.guests (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id) on delete cascade, name text not null check (char_length(name) between 1 and 120), pax integer not null default 1 check (pax between 1 and 50), category text not null default 'Family' check (category in ('Principal','Secondary','Family','Friends','VIP','Others')), email text, phone text, dietary_notes text, guest_message text, decline_reason text, remarks text, listed_by text, rsvp_status public.rsvp_status not null default 'pending', attending_pax integer not null default 0 check (attending_pax between 0 and 50), responded_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index guests_event_id_idx on public.guests(event_id);
create table public.nominated_guests (event_id uuid not null references public.events(id) on delete cascade, name text not null, primary key (event_id, name));
create table public.sponsors (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id) on delete cascade, tier text not null check (tier in ('primary','secondary')), name text not null, position integer not null default 0);
create table public.seating_plans (event_id uuid primary key references public.events(id) on delete cascade, regular_settings jsonb not null default '{"tableCount":0,"maxPerTable":10,"initialized":false}'::jsonb, presidential_settings jsonb not null default '{"tableCount":0,"maxPerTable":10}'::jsonb, paper_size text not null default 'A4' check (paper_size in ('A4','Letter','Legal')), canvas_width integer not null default 1200 check (canvas_width between 400 and 3000), canvas_height integer not null default 700 check (canvas_height between 300 and 2000), elements jsonb not null default '[]'::jsonb, updated_at timestamptz not null default now());
create table public.seat_assignments (event_id uuid not null references public.events(id) on delete cascade, guest_id uuid not null unique references public.guests(id) on delete cascade, table_type text not null check (table_type in ('regular','presidential')), table_number text not null, created_at timestamptz not null default now(), primary key (event_id, guest_id));

create table public.expenses (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id) on delete cascade, supplier_name text not null, expense_type text, cost numeric(14,2) not null default 0 check (cost >= 0), downpayment numeric(14,2) not null default 0 check (downpayment >= 0), contact_person text, contact_number text, payment_status text not null default 'Not Paid' check (payment_status in ('Paid','Incomplete','Not Paid')), payment_tracker text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.tasks (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id) on delete cascade, title text not null, details text, due_date date, status public.task_status not null default 'not_started', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.checklist_items (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id) on delete cascade, title text not null, details text, checked boolean not null default false, position integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.program_items (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id) on delete cascade, title text not null, start_time text, end_time text, details text, position integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.suppliers (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id) on delete cascade, supplier_name text not null, category_type text, quoted_price numeric(14,2) not null default 0 check (quoted_price >= 0), contact_person text, contact_number text, location text, links text check (links is null or links ~ '^https?://'), quote_details text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.invitation_designs (event_id uuid primary key references public.events(id) on delete cascade, template_key text not null default 'garden', published boolean not null default false, content jsonb not null default '{}'::jsonb, theme jsonb not null default '{}'::jsonb, assets jsonb not null default '{}'::jsonb, sections jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
create table public.invitations (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id) on delete cascade, guest_id uuid not null references public.guests(id) on delete cascade, public_token_hash text not null unique, token_version integer not null default 1 check (token_version > 0), status public.invitation_status not null default 'draft', custom_message text, sent_at timestamptz, opened_at timestamptz, responded_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(event_id, guest_id));
create table public.plans (id text primary key, name text not null, entitlements jsonb not null default '{}'::jsonb, active boolean not null default true);
create table public.subscriptions (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, plan_id text references public.plans(id), provider text not null, provider_customer_id text, provider_subscription_id text unique, status text not null, current_period_end timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.billing_webhook_events (provider text not null, provider_event_id text not null, payload jsonb not null, processed_at timestamptz, created_at timestamptz not null default now(), primary key(provider, provider_event_id));
create table public.audit_events (id uuid primary key default gen_random_uuid(), workspace_id uuid references public.workspaces(id) on delete set null, actor_profile_id uuid references public.profiles(id) on delete set null, action text not null, entity_type text not null, entity_id text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());

create or replace function public.touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end; $$;
create trigger profiles_touch before update on public.profiles for each row execute function public.touch_updated_at();
create trigger workspaces_touch before update on public.workspaces for each row execute function public.touch_updated_at();
create trigger events_touch before update on public.events for each row execute function public.touch_updated_at();
create trigger guests_touch before update on public.guests for each row execute function public.touch_updated_at();
alter table public.profiles enable row level security;
alter table public.workspaces enable row level security;
alter table public.workspace_members enable row level security;
alter table public.events enable row level security;
-- Express uses a server-only Postgres role. Add explicit policies before direct client-side Supabase access.
